def prune_2of4(weights):
    out = list(weights)
    for g in range(0, len(weights), 4):
        group = weights[g:g + 4]
        keep = sorted(range(len(group)), key=lambda i: -abs(group[i]))[:2]
        for i in range(len(group)):
            if i not in keep:
                out[g + i] = 0.0
    return out
